export function DotMap({ tone = 'gold' }: { tone?: 'gold' | 'red' }) {
  const dpwList = useMemo(
    () => [
      { id: 'DPW-01', name: 'DPW 1', city: 'Sumatera', x: 48.4, y: 38.5, labelPos: 'right' },
      { id: 'DPW-02', name: 'DPW 2', city: 'Jakarta, Banten, Jabar', x: 104.0, y: 90.1, labelPos: 'bottom' },
      { id: 'DPW-03', name: 'DPW 3', city: 'Jateng, Jatim, Bali-Nusra', x: 144.3, y: 97.5, labelPos: 'bottom' },
      { id: 'DPW-04', name: 'DPW 4', city: 'Kalimantan', x: 152.0, y: 52.6, labelPos: 'top' },
      { id: 'DPW-05', name: 'DPW 5', city: 'Kawasan Timur', x: 190.0, y: 78.1, labelPos: 'right' },
    ],
    []
  );

  const mainColor = tone === 'gold' ? '#ffc20b' : '#ef1c24';
  const fillColor = tone === 'gold' ? 'rgba(255, 194, 11, 0.15)' : 'rgba(239, 28, 36, 0.15)';

  return (
    <div className={`dot-map ${tone}`} style={{ pointerEvents: 'none' }}>
      <svg
        viewBox="0 0 360 130"
        style={{ width: '100%', height: '100%', overflow: 'visible' }}
        role="img"
        aria-label="Peta Distribusi 5 DPW SKATA"
      >
        <defs>
          <filter id={`glow-${tone}`} x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="1.5" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>

        {/* Indonesia Base Map */}
        <path
          d={INDONESIA_SVG_PATH}
          fill={fillColor}
          stroke={mainColor}
          strokeWidth="0.8"
          strokeOpacity="0.6"
        />

        {/* DPW Markers and Labels */}
        {dpwList.map((dpw) => {
          let labelX = dpw.x;
          let labelY = dpw.y;
          let textAnchor: 'start' | 'middle' | 'end' = 'middle';

          if (dpw.labelPos === 'top') {
            labelY = dpw.y - 7;
          } else if (dpw.labelPos === 'bottom') {
            labelY = dpw.y + 11;
          } else if (dpw.labelPos === 'right') {
            labelX = dpw.x + 8;
            labelY = dpw.y + 3;
            textAnchor = 'start';
          }

          return (
            <g key={dpw.id} className="dpw-marker">
              {/* Pulsing Outer Ring */}
              <circle
                cx={dpw.x}
                cy={dpw.y}
                r={6}
                fill="none"
                stroke={mainColor}
                strokeWidth="0.8"
                opacity="0.6"
              >
                <animate
                  attributeName="r"
                  values="3;8;3"
                  dur="2.5s"
                  repeatCount="indefinite"
                />
                <animate
                  attributeName="opacity"
                  values="0.8;0.1;0.8"
                  dur="2.5s"
                  repeatCount="indefinite"
                />
              </circle>

              {/* Core Glowing Dot */}
              <circle
                cx={dpw.x}
                cy={dpw.y}
                r={3.5}
                fill={mainColor}
                filter={`url(#glow-${tone})`}
              />

              {/* City & DPW Label */}
              <text
                x={labelX}
                y={labelY}
                fill="#ffffff"
                fontSize="8.5"
                fontWeight="800"
                textAnchor={textAnchor}
                style={{
                  textShadow: '0 1px 3px rgba(0,0,0,0.95), 0 0 3px #000',
                  letterSpacing: '0.2px',
                }}
              >
                {dpw.name}: {dpw.city}
              </text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}

